previewCss:
.darma-loader-darma-b17-pocket-watch-wind { --accent: var(--loader-color, #a16207); --accent-2: var(--loader-secondary-color, #fef3c7); width: var(--loader-size, 114px); height: var(--loader-size, 114px); position: relative; }
.darma-loader-darma-b17-pocket-watch-wind .darma-loader-darma-b17-pocket-watch-wind__bow { position: absolute; left: 43%; top: 0; width: 14%; height: 11%; border-radius: 999px; box-shadow: inset 0 0 0 3px var(--accent); }
.darma-loader-darma-b17-pocket-watch-wind .darma-loader-darma-b17-pocket-watch-wind__crown { position: absolute; left: 44%; top: 9%; width: 12%; height: 8%; border-radius: 3px; background: repeating-linear-gradient(90deg, var(--accent) 0 24%, color-mix(in srgb, #000 25%, var(--accent)) 0 40%); animation: darma-loader-darma-b17-pocket-watch-wind-watch-wind calc(var(--loader-speed, 1s) * .5) linear infinite; }
.darma-loader-darma-b17-pocket-watch-wind .darma-loader-darma-b17-pocket-watch-wind__case { position: absolute; left: 6%; right: 6%; bottom: 2%; height: 82%; border-radius: 50%; background: radial-gradient(circle at 40% 34%, color-mix(in srgb, #fff 22%, var(--accent-2)), var(--accent-2)); box-shadow: inset 0 0 0 6px var(--accent); }
.darma-loader-darma-b17-pocket-watch-wind .darma-loader-darma-b17-pocket-watch-wind__hand { position: absolute; left: 48%; border-radius: 3px; background: color-mix(in srgb, #000 65%, var(--accent)); transform-origin: 50% 100%; }
.darma-loader-darma-b17-pocket-watch-wind .darma-loader-darma-b17-pocket-watch-wind__hand:nth-of-type(1) { top: 24%; width: 4%; height: 26%; animation: darma-loader-darma-b17-pocket-watch-wind-watch-hour calc(var(--loader-speed, 1s) * 12) linear infinite; }
.darma-loader-darma-b17-pocket-watch-wind .darma-loader-darma-b17-pocket-watch-wind__hand:nth-of-type(2) { top: 14%; width: 3%; height: 36%; animation: darma-loader-darma-b17-pocket-watch-wind-watch-minute calc(var(--loader-speed, 1s) * 2) linear infinite; }
.darma-loader-darma-b17-pocket-watch-wind .darma-loader-darma-b17-pocket-watch-wind__pin { position: absolute; left: 45%; top: 47%; width: 10%; height: 10%; border-radius: 50%; background: var(--accent); }
@keyframes darma-loader-darma-b17-pocket-watch-wind-watch-wind { 0%, 100% { transform: scaleY(1); } 50% { transform: scaleY(.55); } }
@keyframes darma-loader-darma-b17-pocket-watch-wind-watch-hour { to { transform: rotate(1turn); } }
@keyframes darma-loader-darma-b17-pocket-watch-wind-watch-minute { to { transform: rotate(1turn); } }

